/** *path* (one `:parameter`) with its parameter replaced by *key*. */
function documentPath(path, key) {
  return path.replace(/:[^/]+/, key);
}

function escapeHtml(text) {
  return text.replace(/&/g, '&amp;');
}

/** Replaces every deploy-time placeholder in the documents and the bundle; none may remain. */
function substituteDeployTokens(outDir, values) {
  for (const file of filesEnding(outDir, DEPLOY_TOKEN_FILES)) {
    const text = readFileSync(file, 'utf8');
    const html = file.endsWith('.html');
    let replaced = text;
    for (const [token, value] of values) {
      replaced = replaced.split(token).join(html ? escapeHtml(value) : value);
    }
    if (DEPLOY_TOKEN_PREFIXES.some((prefix) => replaced.includes(prefix))) {
      fail(`${file} still carries a deploy-time placeholder its build was not given an input for.`);
    }
    if (replaced !== text) {
      writeFileSync(file, replaced);
    }
  }
}

/**
 * The frames' sandbox tokens, space-separated (possibly none): each a lower-case word, so nothing but a
 * token reaches an attribute or a string literal of the bundle.
 */
function requiredEmbedSandbox() {
  const raw = process.env[EMBED_SANDBOX_INPUT];
  if (raw === undefined) {
    fail(`${EMBED_SANDBOX_INPUT} is required to build a prerendered site that embeds frames and is not set.`);
  }
  const tokens = raw.split(' ').filter((token) => token !== '');
  if (!tokens.every((token) => SANDBOX_TOKEN_PATTERN.test(token))) {
    fail(`${EMBED_SANDBOX_INPUT} must list sandbox tokens (lower-case words joined by "-") separated by spaces.`);
  }
  return tokens.join(' ');
}

/** The name of the referrer the frames send: exactly one of the names the profile model offers. */
function requiredEmbedReferrer() {
  const raw = process.env[EMBED_REFERRER_INPUT];
  if (raw === undefined) {
    fail(`${EMBED_REFERRER_INPUT} is required to build a prerendered site that embeds frames and is not set.`);
  }
  if (!EMBED_REFERRERS.includes(raw)) {
    fail(`${EMBED_REFERRER_INPUT} must be one of ${EMBED_REFERRERS.join(', ')}.`);
  }
  return raw;
}

/**
 * The permission-policy features the frames are delegated, space-separated (possibly none): each one
 * of the features the profile model offers.
 */
function requiredEmbedAllow() {
  const raw = process.env[EMBED_ALLOW_INPUT];
  if (raw === undefined) {
    fail(`${EMBED_ALLOW_INPUT} is required to build a prerendered site that embeds frames and is not set.`);
  }
  const features = raw.split(' ').filter((feature) => feature !== '');
  if (!features.every((feature) => EMBED_ALLOWS.includes(feature))) {
    fail(`${EMBED_ALLOW_INPUT} must list features of ${EMBED_ALLOWS.join(', ')} separated by spaces.`);
  }
  return [...new Set(features)].join(' ');
}

function substituteTokens(files, origin, indexable) {
  const robots = indexable ? ROBOTS_INDEX : ROBOTS_NOINDEX;
  for (const file of files) {
    const text = readFileSync(file, 'utf8');
    const replaced = text.split(ORIGIN_TOKEN).join(origin).split(ROBOTS_TOKEN).join(robots);
    if (TOKEN_PREFIXES.some((prefix) => replaced.includes(prefix))) {
      fail(`${file} still carries a build placeholder after substitution.`);
    }
    if (replaced !== text) {
      writeFileSync(file, replaced);
    }
  }
}

function requireNoInlineScript(files) {
  for (const file of files) {
    const document = new JSDOM(readFileSync(file, 'utf8')).window.document;
    for (const script of document.querySelectorAll('script:not([src])')) {
      const type = (script.getAttribute('type') ?? '').trim().toLowerCase();
      if (!INERT_SCRIPT_TYPES.has(type)) {
        fail(`${file} carries an inline <script> that would execute; the site allows scripts from its own origin only.`);
      }
    }
  }
}

function moveNotFoundDocument(outDir) {
  const source = join(outDir, NOT_FOUND_DIR, 'index.html');
  if (!existsSync(source)) {
    fail(`the build produced no ${NOT_FOUND_DIR}/index.html, the not-found document.`);
  }
  renameSync(source, join(outDir, '404.html'));
  rmSync(join(outDir, NOT_FOUND_DIR), { recursive: true, force: true });
}

function xml(text) {
  return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function pathInLocale(path, locale, defaultLocale) {
  if (locale === defaultLocale) {
    return path;
  }
  return path === '/' ? `/${locale}` : `/${locale}${path}`;
}

/** Every document of the site: the manifest's pages, and a `from(<route>)` page once per key the build read. */
function sitePages(manifest, routeKeys) {
  const listed = manifest.routeSources.flatMap((source) =>
    routeKeys[source.path].map((key) => ({ path: documentPath(source.path, key), noindex: source.noindex })),
  );
  return [...manifest.pages, ...listed];
}

function sitemap(manifest, routeKeys, origin) {
  const { defaultLocale, locales } = manifest;
  const urls = [];
  for (const page of sitePages(manifest, routeKeys)) {
    if (page.noindex) {
      continue;
    }
    const alternates = [
      ...locales.map((locale) => ({ hreflang: locale, href: origin + pathInLocale(page.path, locale, defaultLocale) })),
      { hreflang: 'x-default', href: origin + pathInLocale(page.path, defaultLocale, defaultLocale) },
    ];
    for (const locale of locales) {
      const links = alternates
        .map((alternate) => `    <xhtml:link rel="alternate" hreflang="${xml(alternate.hreflang)}" href="${xml(alternate.href)}"/>`)
        .join('\n');
      urls.push(`  <url>\n    <loc>${xml(origin + pathInLocale(page.path, locale, defaultLocale))}</loc>\n${links}\n  </url>`);
    }
  }
  return (
    '<?xml version="1.0" encoding="UTF-8"?>\n' +
    '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">\n' +
    `${urls.join('\n')}\n</urlset>\n`
  );
}

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

/** The family a TrueType font names itself by (name record 16, else 1, Windows platform): what the card's SVG asks for. */
function fontFamily(name, ttf) {
  const view = new DataView(ttf.buffer, ttf.byteOffset, ttf.byteLength);
  const found = new Map();
  try {
    for (let index = 0; index < view.getUint16(4); index += 1) {
      const record = 12 + index * 16;
      if (String.fromCharCode(...ttf.subarray(record, record + 4)) !== 'name') {
        continue;
      }
      const table = view.getUint32(record + 8);
      const strings = table + view.getUint16(table + 4);
      for (let entry = 0; entry < view.getUint16(table + 2); entry += 1) {
        const at = table + 6 + entry * 12;
        const id = view.getUint16(at + 6);
        if (view.getUint16(at) === 3 && (id === 1 || id === 16) && !found.has(id)) {
          const start = strings + view.getUint16(at + 10);
          const units = [];
          for (let offset = 0; offset < view.getUint16(at + 8); offset += 2) {
            units.push(view.getUint16(start + offset));
          }
          found.set(id, String.fromCharCode(...units));
        }
      }
    }
  } catch {
    fail(`card font '${name}' is not a readable TrueType font once decoded.`);
  }
  const family = found.get(16) ?? found.get(1);
  if (family === undefined || family === '') {
    fail(`card font '${name}' names no family (a Windows-platform name record 1 or 16).`);
  }
  return family;
}

/** Each card font decoded from its WOFF2 file into *directory*, by name: the file the renderer loads, and its family. */
async function cardFonts(key, fonts, directory) {
  const { default: wawoff2 } = await import('wawoff2');
  rmSync(directory, { recursive: true, force: true });
  mkdirSync(directory, { recursive: true });
  const decoded = new Map();
  for (const [name, path] of Object.entries(fonts)) {
    let ttf;
    try {
      ttf = await wawoff2.decompress(readFileSync(join(ROOT, 'apps', key, path)));
    } catch (error) {
      fail(`card font '${name}' (${path}) is not a WOFF2 font: ${error instanceof Error ? error.message : String(error)}`);
    }
    const file = join(directory, `${name}.ttf`);
    writeFileSync(file, ttf);
    decoded.set(name, { file, family: fontFamily(name, ttf) });
  }
  return decoded;
}

/** The colour of each role, held to a hex colour so nothing else reaches an attribute. */
function cardColors(colors) {
  if (!isRecord(colors) || !CARD_COLOR_ROLES.every((role) => typeof colors[role] === 'string' && CARD_COLOR.test(colors[role]))) {
    fail(`the site manifest's card colours are not one hex colour per role (${CARD_COLOR_ROLES.join(', ')}).`);
  }
  return colors;
}

function isCardLine(line) {
  return (
    isRecord(line) &&
    typeof line.text === 'string' &&
    Array.from(line.text).length <= CARD_MAX_LINE_CHARS &&
    Number.isInteger(line.x) && line.x >= 0 && line.x <= CARD_WIDTH &&
    Number.isInteger(line.y) && line.y >= 0 && line.y <= CARD_HEIGHT &&
    CARD_SIZES.has(line.size) &&
    CARD_WEIGHTS.has(line.weight) &&
    CARD_COLOR_ROLES.includes(line.color)
  );
}

/** The laid-out card *file* carries, held to the card's layout; anything else fails the build. */
function documentCard(file, raw, fonts) {
  let card;
  try {
    card = JSON.parse(raw ?? '');
  } catch {
    fail(`${file} carries a card that is not JSON.`);
  }
  if (!isRecord(card) || !Array.isArray(card.lines) || card.lines.length === 0 || card.lines.length > CARD_MAX_LINES) {
    fail(`${file} carries a card that is not between 1 and ${CARD_MAX_LINES} laid-out lines.`);
  }
  if (!card.lines.every(isCardLine)) {
    fail(`${file} carries a card line outside the card's layout.`);
  }
  if (typeof card.logo !== 'string' || !CARD_LOGO_ADDRESS.test(card.logo)) {
    fail(`${file} carries a card whose logo is not one of the site's image files.`);
  }
  if (typeof card.font !== 'string' || !fonts.has(card.font)) {
    fail(`${file} carries a card in a font the site manifest does not list.`);
  }
  return card;
}

/** The logo file as a data URI: the SVG loads nothing from outside itself. */
function logoDataUri(outDir, address) {
  const file = join(outDir, ...address.split('/').filter((part) => part !== ''));
  if (!existsSync(file)) {
    fail(`the card logo ${address} is not in the built site.`);
  }
  const bytes = readFileSync(file);
  const head = bytes.subarray(0, 512).toString('latin1').trimStart();
  let type = null;
  if (bytes[0] === 0x89 && bytes.subarray(1, 4).toString('latin1') === 'PNG') {
    type = 'image/png';
  } else if (bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff) {
    type = 'image/jpeg';
  } else if (head.startsWith('<?xml') || head.startsWith('<svg')) {
    type = 'image/svg+xml';
  }
  if (type === null) {
    fail(`the card logo ${address} is none of the formats the card is drawn with (${CARD_LOGO_FORMATS.join(', ')}).`);
  }
  return `data:${type};base64,${bytes.toString('base64')}`;
}

function cardText(text) {
  return xml(text.replace(XML_INVALID_CHARACTERS, ''));
}

/** The card as an SVG document: every text escaped, the logo inlined, the texts clipped to the padding. */
function cardSvg(card, colors, logo, family) {
  const texts = card.lines
    .map((line) => `<text x="${line.x}" y="${line.y}" font-size="${line.size}" font-weight="${line.weight}" fill="${colors[line.color]}">${cardText(line.text)}</text>`)
    .join('');
  const box = CARD_WIDTH - 2 * CARD_PADDING;
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" width="${CARD_WIDTH}" height="${CARD_HEIGHT}" viewBox="0 0 ${CARD_WIDTH} ${CARD_HEIGHT}">` +
    `<defs><clipPath id="texts"><rect x="${CARD_PADDING}" y="0" width="${box}" height="${CARD_HEIGHT - CARD_PADDING}"/></clipPath></defs>` +
    `<rect width="${CARD_WIDTH}" height="${CARD_HEIGHT}" fill="${colors.background}"/>` +
    `<image href="${logo}" x="${CARD_PADDING}" y="${CARD_PADDING}" width="${CARD_LOGO_SIZE}" height="${CARD_LOGO_SIZE}" preserveAspectRatio="xMinYMin meet"/>` +
    `<g clip-path="url(#texts)" font-family="${xml(family)}">${texts}</g>` +
    '</svg>'
  );
}

/** The URL path a document answers at: its directory under the site, `/` for the root. */
function documentUrlPath(outDir, file) {
  const directory = relative(outDir, dirname(file)).split(sep).filter((part) => part !== '');
  return directory.length === 0 ? '/' : `/${directory.join('/')}`;
}

/** Draws `card.png` beside every document whose page shares a card. */
async function drawCards(key, outDir, files, cards, origin) {
  const { default: resvg } = await import('@resvg/resvg-js');
  const colors = cardColors(cards.colors);
  const fontDirectory = join(ROOT, 'dist', key, 'card-fonts');
  const fonts = await cardFonts(key, cards.fonts, fontDirectory);
  try {
    for (const file of files) {
      const document = new JSDOM(readFileSync(file, 'utf8')).window.document;
      const element = document.querySelector(`meta[name="${CARD_DATA_NAME}"]`);
      if (element === null) {
        continue;
      }
      const card = documentCard(file, element.getAttribute('content'), fonts);
      const path = documentUrlPath(outDir, file);
      const address = `${origin}${path === '/' ? '' : path}/${CARD_FILE_NAME}`;
      if (!file.endsWith(`${sep}index.html`) || document.querySelector('meta[property="og:image"]')?.getAttribute('content') !== address) {
        fail(`${file} shares a card but its og:image is not ${address}, the card the build draws beside it.`);
      }
      const font = fonts.get(card.font);
      const renderer = new resvg.Resvg(cardSvg(card, colors, logoDataUri(outDir, card.logo), font.family), {
        fitTo: { mode: 'original' },
        font: { loadSystemFonts: false, fontFiles: [font.file], defaultFontFamily: font.family },
        logLevel: 'off',
      });
      if (renderer.imagesToResolve().length > 0) {
        fail(`${file}'s card refers to an image outside itself.`);
      }
      const image = renderer.render();
      if (image.width !== CARD_WIDTH || image.height !== CARD_HEIGHT) {
        fail(`${file}'s card was drawn ${image.width}x${image.height}, not ${CARD_WIDTH}x${CARD_HEIGHT}.`);
      }
      writeFileSync(join(dirname(file), CARD_FILE_NAME), image.asPng());
    }
  } finally {
    rmSync(fontDirectory, { recursive: true, force: true });
  }
}

async function finalizeStaticSite(key, manifest, routeKeys) {
  const origin = requiredOrigin();
  const indexable = requiredIndexable();
  const outDir = outputDirectory(key);
  const files = htmlFiles(outDir);
  substituteTokens(files, origin, indexable);
  if (manifest.cards !== null) {
    await drawCards(key, outDir, files, manifest.cards, origin);
  }
  moveNotFoundDocument(outDir);
  const documents = htmlFiles(outDir);
  requireNoInlineScript(documents);
  const robots = indexable
    ? `User-agent: *\nAllow: /\nSitemap: ${origin}/sitemap.xml\n`
    : 'User-agent: *\nDisallow: /\n';
  writeFileSync(join(outDir, 'robots.txt'), robots);
  if (indexable) {
    writeFileSync(join(outDir, 'sitemap.xml'), sitemap(manifest, routeKeys, origin));
  }
}

const key = appKeyFromArguments();
// Validated before the build runs: a missing or malformed deploy-time input never costs a build.
const buildInputs = buildInputsOf(key);
const deployValues = requiredDeployValues(buildInputs);
const manifestPath = join(ROOT, 'apps', key, 'site-manifest.json');
const manifest = existsSync(manifestPath) ? JSON.parse(readFileSync(manifestPath, 'utf8')) : null;
const seededReads = manifest !== null && manifest.seededReads !== undefined ? manifest.seededReads : [];
if (seededReads.length > 0 && !buildInputs.has(SEED_TOLERANT_INPUT)) {
  fail(`the app seeds ${seededReads.length} read(s), and its build takes no ${SEED_TOLERANT_INPUT}: the generated inputs and manifest disagree.`);
}
const seedTolerant = seededReads.length > 0 ? requiredSeedTolerant() : false;
// Read before the build too: the prerender writes one document per key a route lists.
const routeKeys =
  manifest !== null && manifest.routeSources.length > 0 ? await readRouteKeys(manifest.routeSources, requiredApiOrigin()) : {};
// ... and answers each seeded read from the one copy the build made of it.
const seedFile = seededReads.length > 0 ? await writeSeedFile(seededReads, requiredApiOrigin(), seedTolerant) : null;
runBuild(key, routeKeys, seedFile);
substituteDeployTokens(outputDirectory(key), deployValues);
if (manifest !== null) {
  await finalizeStaticSite(key, manifest, routeKeys);
}
